int maximumNumberOfStringPairs(vector<string>& words) {
    int ans = 0;
    for (int i = 0; i < words.size(); i++)
        for (int j = i + 1; j < words.size(); j++)
            if (words[i] == string(words[j].rbegin(), words[j].rend())) ans++;
    return ans;
}

