int maximumNumberOfStringPairs(vector<string>& words) {
    unordered_set<string> seen;
    int ans = 0;
    for (auto& w : words) {
        string r(w.rbegin(), w.rend());
        if (seen.count(r)) ans++;
        else seen.insert(w);
    }
    return ans;
}

