public int maximumNumberOfStringPairs(String[] words) {
    Set<String> seen = new HashSet<>();
    int ans = 0;
    for (String w : words) {
        String r = new StringBuilder(w).reverse().toString();
        if (!seen.add(r)) ans++;
        else seen.remove(r);
    }
    return ans;
}

